"""`paddock init`: wire the scan into GitHub Actions (code scanning) and pre-commit."""
from __future__ import annotations

from pathlib import Path

WORKFLOW_PATH = ".github/workflows/paddock.yml"
PRECOMMIT_PATH = ".pre-commit-config.yaml"

WORKFLOW = """\
# Generated by `paddock init`. Scans dependencies, secrets and code on every push and
# pull request, and shows the results in the repository's Security > Code scanning tab.
name: paddock

on:
  push:
    branches: [main]
  pull_request:
  schedule:
    - cron: "17 5 * * 1"   # weekly, so new advisories against old code are caught

permissions:
  contents: read
  security-events: write   # upload SARIF to code scanning

jobs:
  scan:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-python@v5
        with:
          python-version: "3.12"
      - name: Install paddock
        run: pip install paddock-cli
      - name: Scan
        # Fails the job on high or critical findings; the SARIF file is written either way.
        run: paddock scan --sarif paddock.sarif --fail-on high
      - name: Upload to code scanning
        if: always() && hashFiles('paddock.sarif') != ''
        uses: github/codeql-action/upload-sarif@v3
        with:
          sarif_file: paddock.sarif
          category: paddock
"""

PRECOMMIT_HOOK = """\
  - repo: local
    hooks:
      - id: paddock
        name: paddock (secrets + code)
        # Offline and fast: dependency checks need the network, so they run in CI instead.
        entry: paddock scan --only secrets,code --fail-on high --quiet
        language: system
        pass_filenames: false
        always_run: true
"""

PRECOMMIT = "repos:\n" + PRECOMMIT_HOOK


def init(root: str | Path, *, force: bool = False, workflow: bool = True,
         precommit: bool = True) -> list[tuple[str, str]]:
    """Write the files. Returns [(path, 'created'|'exists'|'snippet')] for the report."""
    root = Path(root)
    out: list[tuple[str, str]] = []
    if workflow:
        p = root / WORKFLOW_PATH
        if p.exists() and not force:
            out.append((WORKFLOW_PATH, "exists"))
        else:
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(WORKFLOW, encoding="utf-8")
            out.append((WORKFLOW_PATH, "created"))
    if precommit:
        p = root / PRECOMMIT_PATH
        if not p.exists():
            p.write_text(PRECOMMIT, encoding="utf-8")
            out.append((PRECOMMIT_PATH, "created"))
        elif "paddock" in p.read_text(encoding="utf-8"):
            out.append((PRECOMMIT_PATH, "exists"))
        else:  # never rewrite someone's existing hook config; show what to add
            out.append((PRECOMMIT_PATH, "snippet"))
    return out
